use std::{fs,path::Path,process::{Command,Stdio}};
fn main(){let a:Vec<_>=std::env::args().collect();let root=Path::new(&a[1]);assert!(!root.exists());fs::create_dir(root).unwrap();let bin=std::env::current_exe().unwrap().with_file_name("geometry631");for k in 0..2{let s=Command::new(&bin).args(["KERNELS.txt","PUBLIC.txt","ALPHA.txt",&k.to_string()]).arg(root.join(format!("kernel{k}"))).stdout(Stdio::from(fs::File::create(root.join(format!("kernel{k}.stdout"))).unwrap())).stderr(Stdio::from(fs::File::create(root.join(format!("kernel{k}.stderr"))).unwrap())).status().unwrap();fs::write(root.join(format!("kernel{k}.status")),format!("exit={:?}\n",s.code())).unwrap();assert!(s.success(),"geometry_failure kernel={k}");println!("CASE_PASS kernel={k}");}println!("COHORT_COMPLETE geometries=2 source_signs_recorded=true no_transfer_or_DLP_claim=true");}
